"""Command line interface for pennywise."""

import argparse
import csv
import io
import json
import os
import sys
from decimal import Decimal

from .ledger import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    parse,
    parse_amount,
    parse_date,
)

PROG = "pennywise"


class _Fail(Exception):
    """Handled failure: carries the exit status and the stderr message."""

    def __init__(self, status, message):
        super().__init__(message)
        self.status = status
        self.message = message


def money(amount):
    """Format an amount with two decimals; never '-0.00'."""
    if amount == 0:
        amount = Decimal(0)
    return format(amount, ".2f")


def format_entry(entry):
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, money(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line


def _date_arg(text):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    parser = argparse.ArgumentParser(
        prog=PROG, description="Report where the money went from a plain-text ledger."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def file_arg(p):
        p.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")

    p = sub.add_parser("balance", help="print the total of all entries")
    file_arg(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    file_arg(p)
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    def filters(p):
        p.add_argument("--category", metavar="C")
        p.add_argument("--since", metavar="DATE", type=_date_arg)
        p.add_argument("--until", metavar="DATE", type=_date_arg)

    p = sub.add_parser("list", help="print entries, oldest first")
    file_arg(p)
    filters(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger file")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    file_arg(p)
    p.add_argument("--format", choices=["csv"], default="csv")
    return parser


def _load(path):
    """Read and parse a ledger; returns entries."""
    shown = "<stdin>" if path == "-" else path
    try:
        if path == "-":
            text = sys.stdin.read()
        else:
            with open(path, encoding="utf-8") as fh:
                text = fh.read()
    except (OSError, UnicodeDecodeError) as exc:
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        raise _Fail(2, "%s: cannot read %s: %s" % (PROG, shown, reason))
    try:
        return parse(text)
    except ParseError as exc:
        raise _Fail(1, "%s: %s: %s" % (PROG, shown, exc))


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)  # stable


def _cmd_balance(args):
    total = balance(_load(args.file))
    if args.json:
        return json.dumps({"balance": money(total)})
    return money(total)


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_month(entries) if args.by == "month" else by_category(entries)
    if args.json:
        return json.dumps({k: money(v) for k, v in totals.items()})
    return "\n".join("%s  %s" % (k, money(v)) for k, v in totals.items())


def _cmd_list(args):
    entries = _sorted(
        filter_entries(
            _load(args.file),
            category=args.category,
            since=args.since,
            until=args.until,
        )
    )
    if args.json:
        return json.dumps(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": money(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return "\n".join(format_entry(e) for e in entries)


def _cmd_export(args):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted(_load(args.file)):
        writer.writerow([e.date.isoformat(), e.category, money(e.amount), e.note])
    return out.getvalue().rstrip("\n")


def _one_line(text):
    return len(("x" + text + "x").splitlines()) == 1


def _build_entry(args):
    """Validate the `add` arguments with the ledger rules; returns an Entry."""
    try:
        date = parse_date(args.date)
        category = args.category
        if len(category.split()) != 1 or category != category.strip():
            raise ValueError(
                "invalid category %r (must be one word without spaces)" % category
            )
        amount = parse_amount(args.amount)
        note = args.note.strip()
        if not _one_line(note):
            raise ValueError("note must not contain a line break")
    except ValueError as exc:
        raise _Fail(1, "%s: invalid entry: %s" % (PROG, exc))
    return Entry(date, category.lower(), amount, note)


def _cmd_add(args):
    if args.file == "-":
        raise _Fail(2, "%s: add does not accept '-' as FILE" % PROG)
    entry = _build_entry(args)
    line = format_entry(entry)
    try:
        prefix = b""
        if os.path.exists(args.file) and os.path.getsize(args.file) > 0:
            with open(args.file, "rb") as fh:
                fh.seek(-1, os.SEEK_END)
                if fh.read(1) != b"\n":
                    prefix = b"\n"
        with open(args.file, "ab") as fh:
            fh.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _Fail(2, "%s: cannot write %s: %s" % (PROG, args.file, exc.strerror or exc))
    return line


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv=None):
    args = _build_parser().parse_args(argv)
    try:
        output = _COMMANDS[args.command](args)
    except _Fail as fail:
        print(fail.message, file=sys.stderr)
        return fail.status
    if output:
        sys.stdout.write(output + "\n")
    return 0
"""Ledger parsing and aggregation."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)


class ParseError(ValueError):
    """A ledger line is malformed. ``line`` is the 1-based line number."""

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text):
    """Strict YYYY-MM-DD -> date. Raises ValueError with a reason."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def parse_amount(text):
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError(
            "invalid amount %r (expected a number with at most two decimals)" % text
        )
    return Decimal(text)


def _parse_line(line):
    fields = line.strip().split(None, 3)
    if len(fields) < 3:
        raise ValueError("expected DATE CATEGORY AMOUNT [NOTE]")
    date = parse_date(fields[0])
    amount = parse_amount(fields[2])
    note = fields[3] if len(fields) == 4 else ""
    return Entry(date, fields[1].lower(), amount, note)


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    entries = []
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if stripped == "" or stripped.startswith("#"):
            continue
        try:
            entries.append(_parse_line(line))
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
    return entries


def balance(entries):
    return sum((e.amount for e in entries), Decimal(0))


def _totals(entries, key):
    totals = {}
    for e in entries:
        k = key(e)
        totals[k] = totals.get(k, Decimal(0)) + e.amount
    return {k: totals[k] for k in sorted(totals)}


def by_category(entries):
    return _totals(entries, lambda e: e.category)


def by_month(entries):
    return _totals(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    if category is not None:
        category = category.lower()
    result = []
    for e in entries:
        if category is not None and e.category.lower() != category:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        result.append(e)
    return result
